$page_security='SA_HRM_ESS_APPROVE_TEAM';$path_to_root='../..';include($path_to_root.'/includes/session.inc');include_once(__DIR__.'/_common.inc');page(_('Team Approvals'));$as_of=hrm_ess_002_today();$msg=null;$err=false;if(isset($_POST['ess2_team_action'])){if(!hrm_ess_002_route_post_valid()){$msg=_('The action was rejected by CSRF protection.');$err=true;}else{$e=null;$res=hrm_ess_002_team_act_on_request((isset($_POST['kind'])?$_POST['kind']:''),(int)((isset($_POST['request_id'])?$_POST['request_id']:0)),(isset($_POST['decision'])?$_POST['decision']:''),(isset($_POST['remarks'])?$_POST['remarks']:''),$as_of,$e);$msg=$res===false?hrm_ess_002_safe_error($e):_('The existing approval workflow accepted the action.');$err=$res===false;}}$leave=hrm_ess_002_team_pending_requests($as_of,'leave');$ot=hrm_ess_002_team_pending_requests($as_of,'overtime');hrm_ess_002_emit_shell_start(_('Team Approvals'),'team');if($msg)hrm_ess_002_ui_status($msg,$err);foreach(array('leave'=>$leave,'overtime'=>$ot) as $kind=>$rows){echo '<h2>'.hrm_ess_002_h($kind==='leave'?_('Leave requests'):_('Overtime requests')).'</h2>';foreach(is_array($rows)?$rows:array() as $row){echo '<form class="ess2-form" method="post"><input type="hidden" name="_token" value="'.hrm_ess_002_h(ensure_csrf_token()).'"><input type="hidden" name="kind" value="'.$kind.'"><input type="hidden" name="request_id" value="'.(int)$row['request_id'].'"><p>'.hrm_ess_002_h($row['employee_id']).' #'.(int)$row['request_id'].'</p><label>'._('Remarks').'<input name="remarks" maxlength="255"></label><div class="ess2-actions"><button name="decision" value="approve" aria-label="'._('Approve scoped request').'">'._('Approve').'</button><button name="decision" value="reject" aria-label="'._('Reject scoped request').'">'._('Reject').'</button><input type="hidden" name="ess2_team_action" value="1"></div></form>';}}hrm_ess_002_emit_shell_end();end_page();
